Task: Extract ORCID identifiers from the provided JSON-LD and compute the average number of pre-2020 works listed on each ORCID profile.
Plan:
- Parse the JSON-LD to get all ORCID identifiers.
- Fetch each ORCID public profile and count works with year < 2020.
- Compute the average across all individuals.
Step 1: Extract ORCID IDs.
Python code:

import json, re
file_path = '/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/bec74516-02fc-48dc-b202-55e78d0e17cf.jsonld'
pattern = re.compile(r'(\d{4}-\d{4}-\d{4}-\d{3}[0-9X])')

def extract_orcids(path):
    with open(path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    found = set()
    def walk(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if isinstance(v, str) and 'orcid.org' in v:
                    m = pattern.search(v)
                    if m:
                        found.add(m.group(1))
                else:
                    walk(v)
        elif isinstance(obj, list):
            for itm in obj:
                walk(itm)
    walk(data)
    return sorted(found)

orcids = extract_orcids(file_path)
print('ORCIDs:', orcids)

I will fetch each ORCID's public profile and count pre-2020 works. I'll use requests with a browser UA string and parse visible years from the 'works' section. If the HTML is insufficient, I'll fall back to the public summary API endpoint.
Python code:

import requests, re, time
from bs4 import BeautifulSoup

orcids = ['0000-0001-6102-7846','0000-0002-0209-2784','0000-0002-1053-2030','0000-0002-2605-6569','0000-0003-0396-0333']
UA = {'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/119 Safari/537.36'}

year_re = re.compile(r'\b(19\d{2}|20\d{2})\b')

def count_pre2020(orcid):
    url = f'https://orcid.org/{orcid}'
    try:
        r = requests.get(url, headers=UA, timeout=15)
        r.raise_for_status()
        soup = BeautifulSoup(r.text, 'html.parser')
        text = soup.get_text(' ')
        years = [int(y) for y in year_re.findall(text) if int(y) < 2020]
        # heuristic: ORCID page lists years per work; approximate count by occurrences of distinct year markers near works
        # To improve, fallback to public works summary JSON
        if len(years) < 5:
            api = f'https://pub.orcid.org/v3.0/{orcid}/works'
            h = {'Accept': 'application/json'}
            z = requests.get(api, headers=h, timeout=15)
            z.raise_for_status()
            data = z.json()
            cnt = 0
            for grp in data.get('group', []):
                for ws in grp.get('work-summary', []):
                    pd = ws.get('publication-date', {})
                    y = pd.get('year', {}).get('value')
                    if y and y.isdigit() and int(y) < 2020:
                        cnt += 1
            return cnt
        else:
            # rough estimate: number of works ~= number of year markers <= 2019
            return len(years)
    except Exception:
        return None

results = {}
for o in orcids:
    time.sleep(1)
    results[o] = count_pre2020(o)

print('Pre-2020 counts:', results)
vals = [v for v in results.values() if isinstance(v, int)]
if vals:
    avg = sum(vals) / len(vals)
    print('Average pre-2020 works:', round(avg, 1))
else:
    print('Average pre-2020 works: N/A')

